@CrossOrigin
@RestController
@RequestMapping("/VisualizationQuery")
public class VisualizationQueryRestController extends BaseSpringRestController {
	
	public VisualizationQueryRestController( VisualizationService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Visualization using a UUID
     * @param		UUID visualizationId
     * @return		Visualization
     */    
    @GetMapping("/load")
    public Visualization load( @RequestParam(required=true) UUID visualizationId ) {
    	Visualization entity = null;

    	try {  
    		entity = service.getVisualization( new VisualizationFetchOneSummary( visualizationId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Visualization using Id " + visualizationId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Visualization business objects
     * @return		Set<Visualization>
     */
    @GetMapping("/")
    public List<Visualization> loadAll() {                
    	List<Visualization> visualizationList = null;
        
    	try {
            // load the Visualization
            visualizationList = service.getAllVisualization();
            
            if ( visualizationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Visualizations" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Visualizations ", exc );
        	return null;
        }

        return visualizationList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Visualization visualization = null;
    protected VisualizationService service = null;
    private static final Logger LOGGER = Logger.getLogger(VisualizationQueryRestController.class.getName());
    
}
